import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class Adder extends JFrame implements ActionListener {
  JTextField t1 = new JTextField(5), t2 = new JTextField(5);
  JButton btn = new JButton("相加");
  JLabel result = new JLabel("结果");
  Adder() {
    setLayout(new FlowLayout());
    add(t1); add(t2); add(btn); add(result);
    btn.addActionListener(this);
    setSize(300, 100);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    int a = Integer.parseInt(t1.getText().trim());
    int b = Integer.parseInt(t2.getText().trim());
    result.setText("和：" + (a + b));
  }
  public static void main(String[] args) {
    new Adder();
  }
}

